        .{ .word = 0x10000688, .op = .vsum2sws },
        .{ .word = 0x10000708, .op = .vsum4sbs },
        .{ .word = 0x10000648, .op = .vsum4shs },
        .{ .word = 0x10000608, .op = .vsum4ubs },
        .{ .word = 0x10000788, .op = .vsumsws },
        .{ .word = 0x180007f0, .op = .vupkd3d128 },
        .{ .word = 0x1000034e, .op = .vupkhpx },
        .{ .word = 0x1000020e, .op = .vupkhsb },
        .{ .word = 0x18000380, .op = .vupkhsb128 },
        .{ .word = 0x1000024e, .op = .vupkhsh },
        .{ .word = 0x100003ce, .op = .vupklpx },
        .{ .word = 0x1000028e, .op = .vupklsb },
        .{ .word = 0x180003c0, .op = .vupklsb128 },
        .{ .word = 0x100002ce, .op = .vupklsh },
        .{ .word = 0x100004c4, .op = .vxor },
        .{ .word = 0x14000310, .op = .vxor128 },
        .{ .word = 0x68000000, .op = .xori },
        .{ .word = 0x6c000000, .op = .xoris },
        .{ .word = 0x7c000278, .op = .xorx },
    };
    for (cases) |c| {
        const got = decodeOp(c.word);
        if (got != c.op) {
            std.debug.print("word=0x{x:0>8} expected {s} got {s}\n", .{ c.word, @tagName(c.op), @tagName(got) });
            return error.DecodeMismatch;
        }
    }
}

test "an unallocated primary opcode decodes to invalid" {
    const unallocated = [_]u32{ 0, 1, 9, 22, 56, 57, 60, 61 };
    for (unallocated) |primary| {
        try std.testing.expectEqual(Op.invalid, decodeOp(primary << 26));
    }
}
